#include "vivarium/recorder.hpp"
#include <fstream>
#include <iomanip>
#include <utility>
namespace vivarium {namespace {std::string esc(const std::string&s){std::string o;for(char c:s){if(c=='"'||c=='\\'){o+='\\';o+=c;}else if(c=='\n')o+="\\n";else if(c=='\r')o+="\\r";else if(c=='\t')o+="\\t";else o+=c;}return o;}void arr(std::ostream&o,const std::vector<double>&v){o<<'[';for(std::size_t i=0;i<v.size();++i){if(i)o<<',';o<<std::setprecision(17)<<v[i];}o<<']';}}
EpisodeRecorder::EpisodeRecorder(std::string id,std::uint64_t seed){episode_.environment_id=std::move(id);episode_.seed=seed;}void EpisodeRecorder::record(const Observation&o,const std::vector<double>&a,const StepResult&r){episode_.frames.push_back({std::uint64_t(episode_.frames.size()),o,a,r.reward,r.terminated,r.truncated});}bool EpisodeRecorder::save_json(const std::string&path,std::string*error)const{std::ofstream out(path);if(!out){if(error)*error="Unable to open output file";return false;}out<<"{\n  \"schema_version\": "<<episode_.schema_version<<",\n  \"environment_id\": \""<<esc(episode_.environment_id)<<"\",\n  \"seed\": "<<episode_.seed<<",\n  \"frames\": [\n";for(std::size_t i=0;i<episode_.frames.size();++i){auto&f=episode_.frames[i];out<<"    {\"step\": "<<f.step<<", \"observation\": ";arr(out,f.observation);out<<", \"action\": ";arr(out,f.action);out<<", \"reward\": "<<std::setprecision(17)<<f.reward<<", \"terminated\": "<<(f.terminated?"true":"false")<<", \"truncated\": "<<(f.truncated?"true":"false")<<'}'<<(i+1<episode_.frames.size()?",":"")<<'\n';}out<<"  ]\n}\n";if(!out){if(error)*error="Failed while writing episode";return false;}return true;}}
